output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the passage is only one cell wide and shelves line both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_single_file_aisle",
    "text": "A shopper must not move from an open area into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEntryIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryIntoSingleFileAisle"
    }
  },
  {
    "id": "park_cart_only_in_wide_clear_cross_aisle",
    "text": "If a shopper leaves a cart behind, the cart must be parked in a wide clear cross-aisle rather than beside shelves or inside a constricted aisle.",
    "abstraction": {
      "state_properties": {
        "wideClearCrossAisle": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "wideClearCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart, the shopper is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "collect_item_after_entering_single_file_aisle",
    "text": "When a shopper enters a single-file shelf aisle on foot, they are obliged to interact with a shelf in that aisle before returning.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "shelfInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileAisleOnFoot",
      "discharge": "shelfInteractionInSingleFileAisle"
    }
  },
  {
    "id": "return_to_cart_after_single_file_aisle",
    "text": "After leaving a single-file shelf aisle without a cart, the shopper is obliged to pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "leaveSingleFileAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileShelfAisle"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileAisleOnFoot",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "wide_shelf_interactions_require_cart",
    "text": "Items reachable from a wide aisle should be taken while keeping the cart, unlike items inside single-file aisles.",
    "abstraction": {
      "state_properties": {
        "wideReachableShelf": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideReachableShelf",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_entry_to_open_merchandise_area",
    "text": "A shopper may not enter the open merchandise aisles without a cart, although they may briefly go cartless into single-file shelf aisles after parking.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "openMerchandiseAisle": {
          "and": [
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                "adjShelf",
                {
                  "lt": [
                    "freeWidthH",
                    12
                  ]
                },
                {
                  "lt": [
                    "freeWidthV",
                    8
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "cartlessEntryToOpenMerchandiseAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              },
              "MOVE"
            ]
          },
          "post": "openMerchandiseAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessEntryToOpenMerchandiseAisle"
    }
  }
]
